function auditF1(raw,e,smoke=false){
 const p=JSON.parse(raw),ok=(b,m)=>{if(!b)throw Error(`${e.ordinal??"smoke"}/${e.count}: ${m}`);};
 const near=(a,b)=>Math.abs(a-b)<=1e-12*Math.max(1,Math.abs(a),Math.abs(b));
 const q=(v,f)=>{const a=[...v].sort((x,y)=>x-y),pos=(a.length-1)*f,i=Math.floor(pos);return a[i]+(a[Math.min(i+1,a.length-1)]-a[i])*(pos-i);};
 const stats=v=>{const median=q(v,.5);return {median,min:Math.min(...v),max:Math.max(...v),mad:q(v.map(x=>Math.abs(x-median)),.5),inclusive_iqr:q(v,.75)-q(v,.25)};};
 const mask=(1n<<64n)-1n;let seed=BigInt(p.seed)^0xd1b54a32d192ed03n;
 const rand=()=>{seed=(seed+0x9e3779b97f4a7c15n)&mask;let z=seed;z=((z^(z>>30n))*0xbf58476d1ce4e5b9n)&mask;z=((z^(z>>27n))*0x94d049bb133111ebn)&mask;return (z^(z>>31n))&mask;};
 const order=[0,1,2,3];for(let i=3;i>0;i--){const j=Number(rand()%BigInt(i+1));[order[i],order[j]]=[order[j],order[i]];}
 ok(JSON.stringify(order)===JSON.stringify(p.initial_variant_order),"seed order");
 ok(p.protocol==="parseatlas_f1_final_reduction_v1"&&p.mode===(smoke?"smoke_not_performance_evidence":"measurement")&&p.timing_claim===!smoke,"mode");
 ok(p.count===e.count&&p.seed===20260905&&p.coordinator_cpu===4&&p.rhs_bytes===p.count*32,"identity");
 ok(p.warmup_rounds===2&&p.measured_rounds===8&&p.preflight.length===4&&p.warmups.length===8&&p.samples.length===32,"record counts");
 ok(p.every_recorded_sample_final_result_compared_exactly===true&&p.every_individual_job_result_checked===false,"check disclosure");
 ok(p.requested_target_ns===(smoke?0:200000000),"target");
 const t=p.topology;
 ok(t.worker_count===8&&JSON.stringify(t.worker_cpus)==="[0,2,6,8,10,12,13,14]"&&t.selection_unit==="physical_core"&&t.observed_allowed_units===10&&!t.coordinator_colocated_worker,"topology frozen");
 const key=cpu=>{const r=t.topology_records.find(x=>x.cpu===cpu);ok(!!r,"topology record");return `${r.package}/${r.core}`;};
 const workers=new Set(t.worker_cpus.map(key));
 ok(workers.size===8&&!workers.has(key(4))&&t.worker_cpus.every(x=>t.inherited_allowed_cpus.includes(x)),"worker separation/eligibility");
 ok(t.reserved_unit_representatives.length===2&&t.reserved_unit_representatives.every(c=>!workers.has(key(c))),"headroom");
 let last=0;
 for(const [phase,rows] of [["preflight",p.preflight],["calibration",p.calibration],["warmups",p.warmups],["samples",p.samples]])for(const s of rows){
  const n=s.count,j=s.jobs,v=s.variant,w=t.worker_count;
  ok(n===p.count&&v>=0&&v<4&&Number.isInteger(j)&&j>=1&&j<=1000000&&n*j<=1000000000,"work cap");
  ok(s.total_rhs_inputs===n*j&&s.source_modular_additions===j*(n+(v===1?4:v===3?w:0)),"denominator/addcount");
  ok(s.source_tree_copied_scalar_elements===(v===2?n*j:0)&&s.source_tree_zero_initialized_scalar_elements===(v===2?n*j:0),"copy/init count");
  ok(s.tree_scratch_bytes_per_job===(v===2?n*32:0)&&s.tree_vector_storage_requests===(v===2?j:0),"tree resources");
  ok(s.cold_partial_bytes_per_job===(v===3?w*32:0)&&s.cold_vector_storage_requests===(v===3?j*3:0),"cold vectors");
  ok(s.source_output_bytes_materialized===j*32&&s.thread_launches===(v===3?j*w:0)&&s.thread_launches<=1000000,"output/thread count");
  ok(Number.isSafeInteger(s.start_steady_ns)&&Number.isSafeInteger(s.stop_steady_ns)&&Number.isSafeInteger(s.elapsed_ns)&&s.elapsed_ns>0,"timestamp range");
  ok(BigInt(s.stop_steady_ns)-BigInt(s.start_steady_ns)===BigInt(s.elapsed_ns)&&s.start_steady_ns>=last,"duration/serial");
  last=s.stop_steady_ns;
  ok(near(s.region_mean_ns_per_full_job,s.elapsed_ns/j)&&near(s.region_mean_ns_per_rhs_input,s.elapsed_ns/j/n),"normalizedmean");
  ok(s.final_checksum===p.reference_final_checksum&&s.cpu_before===4&&s.cpu_after===4,"checksum/cpu");
  const target=(smoke||phase==="preflight")?null:s.elapsed_ns<p.requested_target_ns;
  ok(s.below_requested_target===target,"below flag");
 }
 p.preflight.forEach((s,i)=>ok(s.position===i&&s.round===0&&s.variant===order[i]&&s.jobs===1,"preflight"));
 if(smoke)ok(p.calibration.length===0&&p.jobs_by_variant.every(j=>j===2),"smokejobs");
 else {
  let offset=0;
  for(let pos=0;pos<4;pos++){
    const v=order[pos],rows=p.calibration.filter(s=>s.variant===v);
    ok(rows.length>=1&&rows.length<=8,"calibration count");
    rows.forEach((s,i)=>{ok(p.calibration[offset+i]===s&&s.round===i&&s.position===pos,"calibration order");if(i)ok(s.jobs>rows[i-1].jobs,"calibration growth");});
    offset+=rows.length;
    ok(rows.at(-1).jobs===p.jobs_by_variant[v]&&rows.at(-1).elapsed_ns>=200000000,"final calibration");
  }
  ok(offset===p.calibration.length,"calibration aggregate");
 }
 for(const rows of [p.warmups,p.samples])rows.forEach((s,i)=>ok(s.round===Math.floor(i/4)&&s.position===i%4&&s.variant===order[(s.round+s.position)%4]&&s.jobs===p.jobs_by_variant[s.variant],"round/order/jobs"));
 for(let v=0;v<4;v++){
  const rows=p.samples.filter(s=>s.variant===v),summary=p.summaries.find(s=>s.variant===v);
  ok(rows.length===8&&summary.sample_count===8,"summary count");
  for(let pos=0;pos<4;pos++)ok(rows.filter(s=>s.position===pos).length===2,"position balance");
  for(const metric of ["region_mean_ns_per_full_job","region_mean_ns_per_rhs_input"]){
   for(const [k,val] of Object.entries(stats(rows.map(s=>s[metric]))))ok(near(summary[metric][k],val),"summary "+metric+"/"+k);
  }
  const ratios=rows.map(s=>p.samples.find(b=>b.variant===0&&b.round===s.round).region_mean_ns_per_full_job/s.region_mean_ns_per_full_job);
  ratios.forEach((x,i)=>ok(near(summary.normalized_ratio_by_round[i],x),"ratio"));
  for(const [k,val]of Object.entries(stats(ratios)))ok(near(summary.same_round_serial_over_candidate_normalized_region_mean[k],val),"ratio statistic");
  ok(summary.below_target_count===rows.filter(s=>s.below_requested_target===true).length,"summary below");
 }
 const stamp=k=>BigInt(raw.match(new RegExp('"'+k+'":(\\d+)'))[1]);
 ok(stamp("finished_unix_ns")>stamp("started_unix_ns"),"unix chronology");
 return {ordinal:e.ordinal,count:p.count,series:e.series,status:"pass",started_unix_ns:stamp("started_unix_ns").toString(),finished_unix_ns:stamp("finished_unix_ns").toString(),preflight:p.preflight.length,calibration:p.calibration.length,warmups:p.warmups.length,samples:p.samples.length,below_target:p.samples.filter(s=>s.below_requested_target===true).length,elapsed_ns_range:[Math.min(...p.samples.map(s=>s.elapsed_ns)),Math.max(...p.samples.map(s=>s.elapsed_ns))],jobs_by_variant:p.jobs_by_variant,reference_checksum:p.reference_final_checksum,input_checksum:p.input_checksum_before_and_after,favorable_pairs_by_variant:p.summaries.map(s=>s.normalized_ratio_by_round.filter(x=>x>1).length),summaries:p.summaries};
}
